use crate::{adaptive_simpson,CoreError,CoreResult,Path,PathLocation,Point2,Scalar,Segment,Tolerance,Vector2};
pub fn segment_length(seg:Segment,tol:Tolerance)->CoreResult<Scalar>{match seg{Segment::Line(l)=>Ok(l.length()),Segment::Quadratic(q)=>adaptive_simpson(|t|q.derivative_at(t).length(),0.0,1.0,tol),Segment::Cubic(c)=>adaptive_simpson(|t|c.derivative_at(t).length(),0.0,1.0,tol),Segment::Arc(a)=>adaptive_simpson(|t|a.derivative_at(t).length(),0.0,1.0,tol)}}
pub fn path_length(path:&Path,tol:Tolerance)->CoreResult<Scalar>{let mut n=0.0;for s in path.subpaths(){for &seg in s.segments(){n+=segment_length(seg,tol)?}}Ok(n)}
fn solve_t_for_length(seg:Segment,target:Scalar,total:Scalar,tol:Tolerance)->CoreResult<Scalar>{if total==0.0{return Ok(0.0)}let mut lo=0.0;let mut hi=1.0;for _ in 0..48{let mid=(lo+hi)*0.5;let len=match seg{Segment::Line(_)=>total*mid,Segment::Quadratic(q)=>adaptive_simpson(|t|q.derivative_at(t).length(),0.0,mid,tol)?,Segment::Cubic(c)=>adaptive_simpson(|t|c.derivative_at(t).length(),0.0,mid,tol)?,Segment::Arc(a)=>adaptive_simpson(|t|a.derivative_at(t).length(),0.0,mid,tol)?};if (len-target).abs()<=tol.absolute.max(tol.relative*total){return Ok(mid)}if len<target{lo=mid}else{hi=mid}}Ok((lo+hi)*0.5)}
pub fn point_at_length(path:&Path,distance:Scalar,tol:Tolerance)->CoreResult<(Point2,PathLocation)>{let total=path_length(path,tol)?;if path.is_empty(){return Err(CoreError::DegenerateOperation)}let wanted=distance.clamp(0.0,total);let mut acc=0.0;let mut last=None;for(si,sub)in path.subpaths().iter().enumerate(){for(gi,&seg)in sub.segments().iter().enumerate(){let len=segment_length(seg,tol)?;last=Some((seg,si,gi,acc,len));if wanted<=acc+len||len==0.0{let local=(wanted-acc).clamp(0.0,len);let t=solve_t_for_length(seg,local,len,tol)?;return Ok((seg.point_at(t),PathLocation{subpath_index:si,segment_index:gi,t,distance:wanted}))}acc+=len}}let(seg,si,gi,start,_)=last.ok_or(CoreError::DegenerateOperation)?;Ok((seg.end(),PathLocation{subpath_index:si,segment_index:gi,t:1.0,distance:start}))}
pub fn tangent_at_length(path:&Path,distance:Scalar,tol:Tolerance)->CoreResult<Vector2>{let(_,loc)=point_at_length(path,distance,tol)?;let seg=path.subpaths()[loc.subpath_index].segments()[loc.segment_index];match seg{Segment::Line(l)=>l.direction().normalized(tol),Segment::Quadratic(q)=>q.tangent_at(loc.t,tol),Segment::Cubic(c)=>c.tangent_at(loc.t,tol),Segment::Arc(a)=>a.derivative_at(loc.t).normalized(tol)}}
